-- Pixel width of a text in a LotRO font, from the measured advances in
-- font_widths.lua (generated by tools/fonts/measure_fonts.py), and the font
-- size the game actually renders for a requested size.

import "LUI.src.Settings.enums"
import "LUI.src.Utils.font_widths"

local LUI = _G.LUI
local Utils = LUI.Utils
local LUI_ENUMS = LUI.Settings.Enums
local FONT_CHAR_WIDTHS = Utils.FONT_CHAR_WIDTHS
local FONT_SIZES = Utils.FONT_SIZES

-- normalized font name (as FONT_TO_LOTRO) -> table key prefix
local FAMILY_KEYS = {
    verdana = "Verdana",
    verdanabold = "VerdanaBold",
    arial = "Arial",
    bookantiqua = "BookAntiqua",
    bookantiquabold = "BookAntiquaBold",
    trajanpro = "TrajanPro",
    trajanprobold = "TrajanProBold",
    fixedsys = "FixedSys",
    lucidaconsole = "LucidaConsole",
}

-- characters outside the measured set count as wide as "M", so an unknown
-- glyph can only make the width larger, never clip
local FALLBACK_CHAR = "M"

-- one UTF-8 character
local UTF8_CHAR = "[%z\1-\127\194-\244][\128-\191]*"

-- font name (enum number or string, any spelling) -> family key
local FAMILY_CACHE = {}
-- family key -> requested size -> resolved size
local SIZE_CACHE = {}
-- font name -> requested size -> character width map
local WIDTHS_CACHE = {}

local function _family_key(font_name)
    local family = FAMILY_CACHE[font_name]
    if family ~= nil then
        return family
    end
    local name = font_name
    if type(name) == "number" then
        name = LUI_ENUMS.font_name_to_string[name]
    end
    family = FAMILY_KEYS[string.lower(string.gsub(name, "[%s%-%_]", ""))]
    if family == nil then
        error("No measured widths for font: " .. tostring(font_name))
    end
    FAMILY_CACHE[font_name] = family
    return family
end

-- same rule as FONT_TO_LOTRO: nearest listed size, ties and above-midpoint
-- round up, clamped to the list
local function _choose_size(size, available)
    local count = #available
    if count == 1 or size <= available[1] then
        return available[1]
    end
    if size >= available[count] then
        return available[count]
    end
    for i = 1, count - 1 do
        local lower = available[i]
        local upper = available[i + 1]
        if size < upper then
            if size < (lower + upper) / 2 then
                return lower
            end
            return upper
        end
    end
    return available[count]
end

local function _resolve(family, font_size)
    local sizes = SIZE_CACHE[family]
    if sizes == nil then
        sizes = {}
        SIZE_CACHE[family] = sizes
    end
    local resolved = sizes[font_size]
    if resolved == nil then
        resolved = _choose_size(font_size, FONT_SIZES[family])
        sizes[font_size] = resolved
    end
    return resolved
end

-- ascending list of the sizes the game renders for this font family
function Utils.font_sizes(font_name)
    return FONT_SIZES[_family_key(font_name)]
end

-- size the game renders for a requested (scaled) size
function Utils.resolve_font_size(font_name, font_size)
    return _resolve(_family_key(font_name), font_size)
end

-- character -> pixel advance map for the rendered font; callers measuring
-- in a loop can fetch it once and sum themselves
function Utils.font_char_widths(font_name, font_size)
    local by_size = WIDTHS_CACHE[font_name]
    if by_size == nil then
        by_size = {}
        WIDTHS_CACHE[font_name] = by_size
    end
    local widths = by_size[font_size]
    if widths == nil then
        local family = _family_key(font_name)
        widths = FONT_CHAR_WIDTHS[family .. tostring(_resolve(family, font_size))]
        by_size[font_size] = widths
    end
    return widths
end

local function _sum_widths(text, widths)
    local fallback = widths[FALLBACK_CHAR]
    local total = 0
    for ch in string.gmatch(text, UTF8_CHAR) do
        local width = widths[ch]
        if width == nil then
            width = fallback
        end
        total = total + width
    end
    return total
end

-- whole pixels; font_name is a LUI font name or enum, font_size the size
-- passed to FONT_TO_LOTRO
function Utils.measure_text_width(text, font_name, font_size)
    return _sum_widths(text, Utils.font_char_widths(font_name, font_size))
end

-- game font object (Turbine.UI.Lotro.Font.*) -> character width map and
-- rendered size; built once, for widgets that only keep the font object
-- they were given
local OBJECT_WIDTHS = nil
local OBJECT_SIZES = nil

local function _index_font_objects()
    OBJECT_WIDTHS = {}
    OBJECT_SIZES = {}
    for family, sizes in pairs(FONT_SIZES) do
        for i = 1, #sizes do
            local key = family .. tostring(sizes[i])
            local font = Turbine.UI.Lotro.Font[key]
            OBJECT_WIDTHS[font] = FONT_CHAR_WIDTHS[key]
            OBJECT_SIZES[font] = sizes[i]
        end
    end
end

function Utils.font_object_char_widths(font)
    if OBJECT_WIDTHS == nil then
        _index_font_objects()
    end
    local widths = OBJECT_WIDTHS[font]
    if widths == nil then
        error("No measured widths for font object: " .. tostring(font))
    end
    return widths
end

-- whole pixels for a text drawn with a game font object
function Utils.measure_text_width_in_font(text, font)
    return _sum_widths(text, Utils.font_object_char_widths(font))
end

-- rendered size of a game font object: a multiline label steps its lines
-- by it (measured in game: Verdana18 at 18 px)
function Utils.font_object_size(font)
    if OBJECT_SIZES == nil then
        _index_font_objects()
    end
    local size = OBJECT_SIZES[font]
    if size == nil then
        error("No rendered size for font object: " .. tostring(font))
    end
    return size
end

-- a label wraps this many px (scaled) inside its width (measured in game:
-- a 1010 px line wrapped in a 1018 px label, text drawn ~4 px in): wrap
-- predictions use the label width minus it
Utils.LABEL_WRAP_INSET = 8

-- a label's word wrap of `text` at `max_width` (greedy, as the client
-- wraps): the lines it takes and its widest line. `widths` is a character
-- width map (font_char_widths / font_object_char_widths). An empty line
-- still takes a line; a word wider than max_width breaks inside it.
function Utils.wrap_text(text, max_width, widths)
    local space_w = _sum_widths(" ", widths)
    local count = 0
    local widest = 0
    for line in string.gmatch(text .. "\n", "(.-)\n") do
        count = count + 1
        local line_w = 0
        for word in string.gmatch(line, "%S+") do
            local word_w = _sum_widths(word, widths)
            if line_w > 0 and line_w + space_w + word_w <= max_width then
                line_w = line_w + space_w + word_w
            else
                if line_w > 0 then
                    widest = math.max(widest, line_w)
                    count = count + 1
                end
                line_w = word_w
                while line_w > max_width do
                    widest = max_width
                    count = count + 1
                    line_w = line_w - max_width
                end
            end
        end
        widest = math.max(widest, line_w)
    end
    return count, widest
end

-- memoized measure_text_width for texts that are measured over and over
-- (bestiary drop chips repeat the same item names across thousands of
-- records); keyed by font name, requested size and text
local TEXT_CACHE = {}

function Utils.cached_text_width(text, font_name, font_size)
    local by_size = TEXT_CACHE[font_name]
    if by_size == nil then
        by_size = {}
        TEXT_CACHE[font_name] = by_size
    end
    local by_text = by_size[font_size]
    if by_text == nil then
        by_text = {}
        by_size[font_size] = by_text
    end
    local width = by_text[text]
    if width == nil then
        width = Utils.measure_text_width(text, font_name, font_size)
        by_text[text] = width
    end
    return width
end
